<?php
/** Slice 3 proof — links, the maker's side (spec "Proof" 8 first half): make (shown once, never in the log or the database), the links screen, update, rotate, revoke, never-expires refused unless allowed, who may. */
require __DIR__ . '/lib.php';
$seed = seed_store();
$contracts = $seed['contracts'];
$acme = $seed['board_doc'];

echo "1. Make a link to a document\n";
$m = make_link(27, ['document' => $acme, 'label' => 'for the auditor', 'expires_in_days' => 30, 'allow_download' => 'yes']);
ok($m['r']['code'] === 200 && $m['link_id'] > 0 && preg_match('#^/s/[a-f0-9]{48}$#', $m['path']) === 1 && str_contains($m['r']['json']['did'] ?? '', 'Made the link for the auditor'), 'link_make: ok, the link\'s id, the URL once in the answer');
ok(str_ends_with($m['r']['json']['location'] ?? '', '/documents/' . $acme . '/links?made=' . $m['link_id'] . '&notice=made#link-url-once'), '...lands on the links screen with the once-shown URL');
$raw = $m['raw'];
ok((int) one('SELECT count(*) FROM share_links WHERE token_hash = :h', ['h' => hash('sha256', $raw)]) === 1 && (int) one("SELECT count(*) FROM share_links WHERE token_hash = :r OR note = :r OR label = :r", ['r' => $raw]) === 0, 'the database holds the hash, never the token');
ok((int) one("SELECT count(*) FROM activity_log WHERE after::text LIKE :r OR before::text LIKE :r OR route LIKE :r", ['r' => '%' . $raw . '%']) === 0, 'the token is in no log row');
$ev = last_event('link.make');
ok($ev !== null && (int) $ev['document_id'] === $acme && json_decode($ev['after'], true)['label'] === 'for the auditor' && json_decode($ev['after'], true)['has_password'] === false, 'logged link.make with the label, never the password');
$l = q('SELECT * FROM share_links WHERE id = :id', ['id' => $m['link_id']])[0];
ok($l['kind'] === 'view' && (bool) $l['allow_download'] && $l['password_hash'] === null && strtotime($l['expires_at']) > time() + 29 * 86400 && (int) $l['made_by'] === 27, 'kind view, download allowed, no password, expires in 30 days, made by Marco');

echo "2. The links screen\n";
$r = page(actor(27), '/documents/' . $acme . '/links');
ok($r['code'] === 200 && str_contains($r['body'], 'id="links-table"') && str_contains($r['body'], 'id="link-row-' . $m['link_id'] . '"') && str_contains($r['body'], 'data-state="live"') && str_contains($r['body'], 'id="link-new-btn"'), 'the document\'s links screen lists the live link');
ok(!str_contains($r['body'], $raw), 'the URL is not on the screen after the once');
$r = page(actor(27), '/documents/' . $acme . '/links?made=' . $m['link_id']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="link-url-input"') && str_contains($r['body'], $raw), '…?made= once: the URL with Copy');
$r = page(actor(27), '/documents/' . $acme . '/links?made=' . $m['link_id']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="link-url-gone"') && !str_contains($r['body'], $raw), '…?made= again: "shown once already", the token gone');
$j = get_json(27, '/documents/' . $acme . '/links')['json']['data'] ?? [];
ok(($j['links'][0]['link_id'] ?? 0) === $m['link_id'] && ($j['links'][0]['state'] ?? '') === 'live' && !isset($j['links'][0]['token_hash']) && !isset($j['links'][0]['password_hash']), 'the JSON: the link, its state, no hash');
ok(page(actor(26), '/documents/' . $acme . '/links')['code'] === 403 && page(actor(28), '/documents/' . $acme . '/links')['code'] === 404, 'an editor sees no links screen (403); a stranger 404');
$r = page(actor(27), '/links/new?document=' . $acme);
ok($r['code'] === 200 && str_contains($r['body'], 'id="link-form"') && !str_contains($r['body'], '>never<'), 'the link form; "never" is not offered (the setting forbids it)');

echo "3. Never, the password, a folder link\n";
$r = post_j(27, '/links/make.php', ['document' => $acme, 'label' => 'forever', 'expires_in_days' => 0]);
ok($r['code'] === 422 && ($r['json']['error']['fields']['expires_in_days'] ?? '') !== '', 'a link that never expires is refused (the admin has not allowed it)');
pdo()->exec("UPDATE dc_settings SET link_no_expiry_allowed = true");
$r = post_j(27, '/links/make.php', ['document' => $acme, 'label' => 'forever', 'expires_in_days' => 0]);
ok($r['code'] === 200 && one('SELECT expires_at FROM share_links WHERE id = :id', ['id' => (int) $r['json']['record_id']]) === null, '...allowed by the admin: no expiry');
pdo()->exec("UPDATE dc_settings SET link_no_expiry_allowed = false");
$pw = make_link(27, ['document' => $acme, 'label' => 'with a password', 'password' => 'open sesame', 'allow_download' => 'no']);
$lp = q('SELECT * FROM share_links WHERE id = :id', ['id' => $pw['link_id']])[0];
ok($pw['r']['code'] === 200 && $lp['password_hash'] !== null && password_verify('open sesame', $lp['password_hash']) && !(bool) $lp['allow_download'], 'a password link: hashed, view only');
$r = post_j(27, '/links/make.php', ['document' => $acme, 'label' => 'short pw', 'password' => 'abc']);
ok($r['code'] === 422, 'a password under 4 characters: 422');
$r = post_j(27, '/links/make.php', ['document' => $acme, 'label' => str_repeat('x', 121)]);
ok($r['code'] === 422 && ($r['json']['error']['fields']['label'] ?? '') !== '', 'a label over 120 characters: 422 on the field');
$f = make_link(27, ['folder' => $contracts, 'label' => 'contracts folder', 'expires_in_days' => 7, 'note' => 'Here are the contracts.']);
ok($f['r']['code'] === 200 && (int) one('SELECT folder_id FROM share_links WHERE id = :id', ['id' => $f['link_id']]) === $contracts, 'a folder link');
$r = page(actor(27), '/folders/' . $contracts . '/links');
ok($r['code'] === 200 && str_contains($r['body'], 'id="link-row-' . $f['link_id'] . '"') && str_contains($r['body'], 'data-state="expiring"') && str_contains($r['body'], 'id="requests-table"') && str_contains($r['body'], 'id="request-new-btn"'), 'the folder\'s links screen: the link expiring within 7 days, the requests table, Request files');

echo "4. Update, rotate, revoke\n";
$r = post_j(27, '/links/update.php', ['link' => $m['link_id'], 'label' => 'for the auditors', 'allow_download_sent' => '1', 'expires_in_days' => 3]);
$l2 = q('SELECT * FROM share_links WHERE id = :id', ['id' => $m['link_id']])[0];
ok($r['code'] === 200 && $l2['label'] === 'for the auditors' && !(bool) $l2['allow_download'] && strtotime($l2['expires_at']) < time() + 4 * 86400 && $l2['token_hash'] === $l['token_hash'], 'link_update: the label, download off (the box unticked), expiry shortened — the same token');
$r = post_j(27, '/links/update.php', ['link' => $m['link_id'], 'password' => 'secret1']);
ok($r['code'] === 200 && one('SELECT password_hash FROM share_links WHERE id = :id', ['id' => $m['link_id']]) !== null, '...a password set');
$r = post_j(27, '/links/update.php', ['link' => $m['link_id'], 'password' => '']);
ok($r['code'] === 200 && one('SELECT password_hash FROM share_links WHERE id = :id', ['id' => $m['link_id']]) !== null, '...blank keeps it');
$r = post_j(27, '/links/update.php', ['link' => $m['link_id'], 'password' => 'none']);
ok($r['code'] === 200 && one('SELECT password_hash FROM share_links WHERE id = :id', ['id' => $m['link_id']]) === null, '...the word none removes it');
ok(last_event('link.update') !== null && json_decode(last_event('link.update')['before'], true)['has_password'] === true, 'logged link.update with before/after facts');
$r = post_j(27, '/links/rotate.php', ['link' => $m['link_id']]);
$nid = (int) ($r['json']['record_id'] ?? 0);
$newUrl = (string) ($r['json']['url'] ?? '');
ok($r['code'] === 200 && $nid > 0 && $nid !== $m['link_id'] && preg_match('#/s/[a-f0-9]{48}$#', $newUrl) === 1 && substr($newUrl, -48) !== $raw, 'link_rotate: a new link with a new token');
ok(one('SELECT rotated_at FROM share_links WHERE id = :id', ['id' => $m['link_id']]) !== null && one('SELECT label FROM share_links WHERE id = :id', ['id' => $nid]) === 'for the auditors', 'the old link is rotated out; the new carries the label');
ok(req('GET', $m['path'])['code'] === 404 && req('GET', (string) parse_url($newUrl, PHP_URL_PATH))['code'] === 200, 'the old URL is 404, the new one 200');
$r = post_j(27, '/links/rotate.php', ['link' => $m['link_id']]);
ok($r['code'] === 422, 'rotating a rotated link: 422');
$r = post_j(26, '/links/revoke.php', ['link' => $nid]);
ok($r['code'] === 403, 'an editor (not the maker, not a manager): 403');
$r = post_j(27, '/links/revoke.php', ['link' => $nid]);
ok($r['code'] === 200 && one('SELECT revoked_at FROM share_links WHERE id = :id', ['id' => $nid]) !== null && last_event('link.revoke') !== null, 'link_revoke by the maker; logged');
ok(req('GET', (string) parse_url($newUrl, PHP_URL_PATH))['code'] === 404, 'the revoked URL is 404');
$r = post_j(1, '/links/revoke.php', ['link' => $f['link_id']]);
ok($r['code'] === 200, 'the admin (links.all) revokes anyone\'s link');
$r = page(actor(27), '/documents/' . $acme . '/links');
ok(substr_count($r['body'], 'data-state="revoked"') >= 1 && substr_count($r['body'], 'data-state="rotated"') === 1, 'the screen shows the revoked and the rotated below the live');
$r = page(actor(27), '/documents/' . $acme . '/links?opens=' . $pw['link_id']);
ok($r['code'] === 200 && str_contains($r['body'], 'id="link-opens-table"'), 'the opens table of a link');
finish();
